Lemma global_local_width_62 v (H0:size (global_word_53 v)=8%nat) : size (global_word_62 v)=1%nat.
Proof. have T : env_typed (global_closed_62 v).
 { unfold global_closed_62. repeat (apply env_typed_add; [|cbn [hvalue_is_type_correct type_of_val]; rewrite ?H0 ?eqxx; reflexivity]). apply env_typed_empty. }
 have E := scalar_eval_type_correct (global_closed_62 v) (global_closed_62 v) global_expr_62 T (Logic.eq_refl _).
 rewrite global_closed_62_value in E.
 have K : eval_type_of_expr global_expr_62 (global_closed_62 v) = Some (Gtyp (Fuint 1)) by reflexivity.
 rewrite K in E.
 exact (uint_value_typed_size _ _ _ E).
Qed.
